"use client";

import Link from "next/link";
import { useState } from "react";

const NAV_LINKS = [
  { label: "Vêtements", href: "/boutique/vetements" },
  { label: "Accessoires", href: "/boutique/accessoires" },
  { label: "Collections", href: "/collections" },
  { label: "Atelier", href: "/atelier" },
];

export default function SiteHeader() {
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <header className="relative z-30">
    
      {/* Masthead — logotype central façon nameplate de journal */}
      <div className="flex items-center justify-between px-6 lg:px-10 py-6">
        <button
          className="md:hidden font-body text-sm uppercase tracking-wide"
          onClick={() => setMenuOpen((v) => !v)}
          aria-expanded={menuOpen}
          aria-controls="mobile-nav"
        >
          {menuOpen ? "Fermer" : "Menu"}
        </button>

        <Link
          href="/"
          className="mx-auto md:mx-0 md:absolute md:left-1/2 md:-translate-x-1/2 font-display text-3xl lg:text-4xl tracking-tight"
        >
          <div className="header_logo">
            <img src="/visual_assets/flamerz_logo.png" alt="" />
          </div>
        </Link>

        <Link
          href="/panier"
          className="md:hidden font-body text-sm uppercase tracking-wide"
        >
          Panier
        </Link>

        {/* Nav catégories desktop */}
        <nav className="hidden md:flex ml-auto gap-8 font-body text-sm uppercase tracking-wide">
          {NAV_LINKS.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              className="relative pb-1 hover:text-brick transition-colors after:absolute after:left-0 after:bottom-0 after:h-px after:w-0 after:bg-brick after:transition-all hover:after:w-full"
            >
              {link.label}
            </Link>
          ))}
        </nav>
      </div>

      {/* Nav mobile */}
      {menuOpen && (
        <nav
          id="mobile-nav"
          className="md:hidden flex flex-col border-t border-line/70 bg-paper"
        >
          {NAV_LINKS.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              className="px-6 py-4 border-b border-line/40 font-display text-xl"
              onClick={() => setMenuOpen(false)}
            >
              {link.label}
            </Link>
          ))}
        </nav>
      )}
    </header>
  );
}
